<script>
(function() {
  const SELECTOR = {
    wrapper: '.stellar-wrapper.stellar-pending',
    panel: '.stellar-panel',
    grid: '.options-grid',
    footer: '.action-footer',
    hint: '.hint-text',
    toggle: '.collapse-hint',
    submit: '.submit-action',
    rawData: '.raw-choices'
  };

  function findTextarea() {
    try {
      const parentDoc = window.parent?.document;
      return parentDoc?.querySelector('#send_textarea') ?? document.querySelector('#send_textarea');
    } catch { return null; }
  }

  function collectSelections(grid) {
    return [...grid.querySelectorAll('.choice-cell.selected')]
      .map(el => el.dataset.value || '')
      .filter(Boolean);
  }

  function readCurrentInput(grid) {
    const textarea = findTextarea();
    const inputVal = textarea?.value?.trim() ?? '';
    return inputVal || collectSelections(grid).join(' ').trim();
  }

  function dispatchMessage(grid) {
    const msg = readCurrentInput(grid);
    if (!msg) return;

    try {
      const slash = window.triggerSlash ?? window.parent?.triggerSlash;
      if (typeof slash === 'function') {
        slash(`/send ${msg}|/trigger`);
      } else {
        const textarea = findTextarea();
        if (textarea) {
          textarea.value = msg;
          textarea.dispatchEvent(new Event('input', { bubbles: true }));
          textarea.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }));
        }
      }

      const container = grid.closest('.stellar-wrapper');
      if (container) {
        container.classList.add('dismissing');
        setTimeout(() => { container.style.display = 'none'; }, 260);
      }
    } catch (err) {
      console.error('发送失败:', err);
    }
  }

  function syncUI(grid, submitBtn) {
    const textarea = findTextarea();
    const selections = collectSelections(grid);
    const combined = selections.join(' ');

    if (textarea) {
      textarea.value = combined;
      textarea.focus();
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    }

    if (submitBtn) {
      const hasContent = (textarea?.value ?? combined).trim().length > 0;
      submitBtn.disabled = !hasContent;
    }
  }

  function setupResponsiveLayout(footer, hintText, submitBtn) {
    if (!footer || !hintText || !submitBtn) return;

    const adjust = () => {
      if (window.innerWidth >= 880) {
        footer.classList.add('float-layout');
        if (!hintText.contains(submitBtn)) {
          hintText.insertAdjacentElement('afterbegin', submitBtn);
        }
      } else {
        footer.classList.remove('float-layout');
        if (submitBtn.parentElement !== footer) {
          footer.appendChild(submitBtn);
        }
      }
    };

    adjust();
    let pending;
    window.addEventListener('resize', () => {
      cancelAnimationFrame(pending);
      pending = requestAnimationFrame(adjust);
    });
  }

  function bootstrap() {
    document.querySelectorAll(SELECTOR.wrapper).forEach(wrapper => {
      const panel = wrapper.querySelector(SELECTOR.panel);
      const grid = wrapper.querySelector(SELECTOR.grid);
      const footer = wrapper.querySelector(SELECTOR.footer);
      const toggle = wrapper.querySelector(SELECTOR.toggle);
      const rawData = wrapper.querySelector(SELECTOR.rawData);

      // 折叠切换
      if (panel && toggle) {
        panel.addEventListener('toggle', () => {
          toggle.textContent = panel.open ? '收起' : '展开';
        });
      }

      // 解析选项
      if (grid && rawData) {
        const text = rawData.innerHTML.replace(/<br\s*\/?>/gi, '\n');
        const pattern = /\d+[\.。、]\s*([^\n\r]+)/g;
        let match, idx = 1;

        while ((match = pattern.exec(text)) !== null) {
          const content = (match[1] || '').trim();
          if (!content) continue;

          const cell = document.createElement('button');
          cell.className = 'choice-cell';
          cell.dataset.value = content;
          cell.textContent = `${idx}. ${content}`;

          cell.addEventListener('click', e => {
            e.preventDefault();
            cell.classList.toggle('selected');
            const parentGrid = cell.closest('.options-grid');
            if (parentGrid) syncUI(parentGrid, wrapper.querySelector(SELECTOR.submit));
          });

          grid.appendChild(cell);
          idx++;
        }
        rawData.remove();
      }

      // 底部栏初始化
      let submitBtn = footer?.querySelector(SELECTOR.submit);
      const hintLabel = footer?.querySelector('.hint-label');
      const hintText = footer?.querySelector(SELECTOR.hint);

      if (!hintText?.textContent?.trim() && hintLabel) {
        hintLabel.style.display = 'none';
      }

      if (footer) {
        footer.style.display = 'grid';

        if (!submitBtn) {
          submitBtn = document.createElement('button');
          submitBtn.className = 'submit-action';
          submitBtn.type = 'button';
          submitBtn.textContent = '确认发送';
          submitBtn.disabled = true;
          footer.appendChild(submitBtn);
        }

        submitBtn.addEventListener('click', () => {
          const targetGrid = wrapper.querySelector(SELECTOR.grid);
          if (targetGrid) dispatchMessage(targetGrid);
        });

        setupResponsiveLayout(footer, hintText, submitBtn);
      }

      syncUI(grid, submitBtn);
      wrapper.classList.remove('stellar-pending');
    });
  }

  if (typeof window.stellarOptionsInit === 'undefined') {
    window.stellarOptionsInit = bootstrap;
  }
  bootstrap();
})();
</script>
